/** Preguntas de ampliación: casos de aplicación, errores habituales y decisiones de diseño. */
'use strict';

function addQuestions(topic, prefix, rows) {
  return rows.map(([prompt, options, answer, explanation, difficulty], index) => ({
    id: prefix + '-' + String(index + 1).padStart(2, '0'),
    topic,
    q: prompt,
    o: options,
    a: answer,
    e: explanation,
    difficulty
  }));
}

